WITH watch_orders AS (SELECT DISTINCT o.order_id, strftime(o.order_purchase_timestamp, '%Y-%m') AS month FROM olist_orders_dataset o JOIN olist_customers_dataset c ON o.customer_id = c.customer_id JOIN olist_order_items_dataset oi ON oi.order_id = o.order_id JOIN olist_products_dataset p ON p.product_id = oi.product_id WHERE o.order_status = 'delivered' AND c.customer_state = 'SP' AND p.product_category_name = 'watches_gifts' AND o.order_purchase_timestamp >= TIMESTAMP '2018-07-01 00:00:00' AND o.order_purchase_timestamp < TIMESTAMP '2018-09-01 00:00:00'), item_agg AS (SELECT oi.order_id, SUM(oi.price) AS item_sales FROM olist_order_items_dataset oi JOIN olist_products_dataset p ON p.product_id = oi.product_id WHERE p.product_category_name = 'watches_gifts' GROUP BY oi.order_id), pay_agg AS (SELECT order_id, SUM(payment_value) AS payments FROM olist_order_payments_dataset GROUP BY order_id) SELECT w.month, COUNT(DISTINCT w.order_id) AS order_count, ROUND(SUM(ia.item_sales), 2) AS item_sales, ROUND(SUM(pa.payments), 2) AS payments, ROUND(SUM(pa.payments) - SUM(ia.item_sales), 2) AS payment_minus_item FROM watch_orders w LEFT JOIN item_agg ia ON ia.order_id = w.order_id LEFT JOIN pay_agg pa ON pa.order_id = w.order_id GROUP BY w.month ORDER BY w.month